import{_ as l,l as n,o as e,c as i,v as t,p as s,x as r,d as p,i as E,S as m}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"总量管制与许可证","description":"","frontmatter":{"title":"总量管制与许可证","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cap-and-trade.md","filePath":"econ/cap-and-trade.md","lastUpdated":1789023840000}'),A={name:"econ/cap-and-trade.md"};function d(h,a,c,_,B,u){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="总量管制与许可证" tabindex="-1">总量管制与许可证 <a class="header-anchor" href="#总量管制与许可证" aria-label="Permalink to &quot;总量管制与许可证&quot;">​</a></h1><div class="epigraph"><p>先把允许的排放钉成总量，再把许可证交给市场去交易；竞争许可市场把减污做到等边际，初始分配只改谁付钱。</p><footer>—— 据 Dales, Pollution, Property and Prices, 1968；Montgomery, Markets in Licenses and Efficient Pollution Control Programs, Journal of Economic Theory, 1972 整理</footer></div><p><a href="/econ/coase-theorem">上一课</a>（科斯定理与交易成本）。零成本谈判下，排放权的初始归属只改分配，不改有效 \\(q^*\\)。本课不重写相互性与摩擦那一半。缺口是政策工具：计划者若不能一对一谈判，也不想猜准<a href="/econ/externality-pigou">庇古</a>税率，能否发一笔可交易许可，让市场去找同一点？Dales 提出把环境当成可分割产权；Montgomery 证明竞争许可市场达到成本有效。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>庇古税钉价格 \\(t=\\mathrm{MD}(q^*)\\)，数量内生。科斯说权利可交易。总量管制选 \\(Q^*\\)（希望 \\(Q^*=Q_{\\mathrm{社会最优}}\\)），发许可 \\(\\sum e_i\\le Q^*\\)，允许转卖。竞争下许可价格 \\(p_{\\ell}\\) 使各厂减污的边际成本对齐到 \\(p_{\\ell}\\)，总减污成本最小——不管许可最初发给谁（科斯在政策上的版本）。缺口不是再画 \\(\\mathrm{MD}\\)，而是：<strong>数量工具与价格工具何时等价，初始分配改什么、不改什么。</strong></p><p>厂商成本异质时，命令式「每家减同样百分比」不是成本有效。许可交易正是为了让减污发生在 MAC 低的厂。税也能对齐 MAC（大家都面对同一 \\(t\\)）；差别在不确定与政治：税把价格钉死、排放浮动；封顶把数量钉死、许可价浮动。</p><h3 id="可交易许可不是庇古税换了单位" tabindex="-1">可交易许可不是庇古税换了单位 <a class="header-anchor" href="#可交易许可不是庇古税换了单位" aria-label="Permalink to &quot;可交易许可不是庇古税换了单位&quot;">​</a></h3><p>确定性、完全信息、竞争下，选 \\(Q^*\\) 使 \\(p_{\\ell}=\\mathrm{MD}(Q^*)\\)，与选 \\(t=\\mathrm{MD}\\) 同一配置。等价在 Weitzman 的斜率比较下破裂：MAC 不确定时，数量与价格的相对优劣取决于 \\(\\mathrm{MD}\\) 与 MAC 谁更陡。本课先钉确定基准，不确定放边界。</p><p><span class="marginnote">Montgomery 1972：许可在空间上若要对应扩散，许可证应分地点或用转换系数，否则交易会把污染赶到敏感区。教具先当均匀混合污染物，一单位许可一单位排放。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：竞争厂商、许可可分可转卖、无市场势力。成本有效：\\(\\min\\sum C_i(e_i)\\) s.t. \\(\\sum e_i\\le Q^*\\)。许可市场的 \\(p_{\\ell}\\) 是该约束的乘数。初始分配 \\(e_i^0\\) 只改谁向谁买许可，不改 \\(e_i^*\\)（科斯）。计划者仍要选对 \\(Q^*\\)；选错总量，交易只能在错误的帽子里做成本有效，不能把帽子本身纠正到社会最优。</p><p>与命令控制对照：同样 \\(Q^*\\)，不许交易则 MAC 不对齐，同样环境目标更贵。税：计划者要猜 \\(t\\)；许可：猜 \\(Q\\)。信息负担从税率挪到总量，不是消失。拍卖发放把租金收进预算；免费发放只改分配，竞争下不改 \\(e_i^*\\)。</p>',12)),(e(),s(m,null,{default:r(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20COASE%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E6%9D%83%E5%88%A9%E5%8F%AF%E8%B0%88%22%5D%20--%3E%20CAP%5B%22%E6%94%BF%E7%AD%96%EF%BC%9A%E9%92%89%20Q*%20%E5%86%8D%E8%AE%A9%E8%AE%B8%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%0A%20%20PIGOU%5B%22%E5%BA%87%E5%8F%A4%EF%BC%9A%E9%92%89%20t%22%5D%20--%3E%20EQV%5B%22%E7%A1%AE%E5%AE%9A%E4%B8%8B%E5%8F%AF%E7%AD%89%E4%BB%B7%22%5D%0A%20%20CAP%20--%3E%20MAC%5B%22%E7%AB%9E%E4%BA%89%E8%AE%B8%E5%8F%AF%EF%BC%9AMAC%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20CAP%20--%3E%20DIST%5B%22%E5%88%9D%E5%A7%8B%E5%88%86%E9%85%8D%E5%8F%AA%E6%94%B9%E8%B0%81%E4%BB%98%E9%92%B1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>人数很多时，科斯谈判组不起来，许可市场用价格代替双边讨价还价——这是把权利标准化之后的匿名交易，不是全人口联盟。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对齐 MAC 的机制与要素市场同一：共同 \\(p_{\\ell}\\) 让每家的减污一阶条件相同。初始分配无关效率的机制就是科斯：许可是禀赋，交易补全这维商品。税与数量在确定下等价的机制是：一条向下的 \\(\\mathrm{MD}\\) 与一条向上的 MAC，交点既可用纵轴的税、也可用横轴的帽去钉。</p><p>计划者仍须知道有效点才能选对帽——与庇古要知道 \\(\\mathrm{MD}(q^*)\\) 是对称的信息。许可的政治优点往往是：把 \\(Q^*\\) 当成环境目标更可沟通，再让市场找谁减。</p><p>Weitzman：MAC 随机时，税锁定边际激励、排放浮动；帽锁定排放、许可价浮动。\\(\\mathrm{MD}\\) 很陡（阈值损害）时数量工具更安全；MAC 很陡时价格工具少付「选错帽」的成本。本课确定基准上二者等价，不确定时要另写损失函数，不要口头说「许可永远优于税」。</p><p><span class="marginnote">许可市场若被少数厂操纵，\\(p_{\\ell}\\) 不再等于影子成本，成本有效失败。这与产品市场势力是同一缺口，不是科斯零成本假设的一部分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>银行把单期帽拉成跨期路径，仍靠竞争许可对齐跨期 MAC。</p><p>热点、跨界输送，要分区许可或交换比率，Montgomery 的空间版本。动态银行（banking）把帽跨期，本课单期。免费发放与拍卖只改分配与公共收入，不改竞争下的 \\(e_i^*\\)——除非市场势力或流动性约束让有人买不起许可。下一课<a href="/econ/public-goods">公共物品</a>把非排他推到极端：许可假定排放可测、可排除未持证者；纯公共品连「不付费者不享用」都做不到。</p><p>后课默认：可交易许可在竞争下成本有效，初始分配只改分配；与庇古税在确定世界等价，帽选错则有效点一起错。</p><p>本课不把许可市场写成一对一科斯谈判。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总量钉住环境目标，交易把减污分给 MAC 低的厂。</li><li>竞争许可是标准化的科斯权利，不是一对一谈判。</li><li>确定下与庇古税等价；不确定下价格对数量要另比斜率。</li><li>下一课：不能排除的公共品，连许可都组不起来。</li><li>出处：Dales, 1968；Montgomery, <em>JET</em>, 1972。</li></ul>',13))])}const M=l(A,[["render",d]]);export{D as __pageData,M as default};
